data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
wells = [int(data[2 + i]) for i in range(n)]
pipes = []
pos = 2 + n
for _ in range(m):
    pipes.append((int(data[pos]), int(data[pos + 1]), int(data[pos + 2])))
    pos += 3
best = None
for wmask in range(1, 1 << n):
    for pmask in range(1 << m):
        comp = list(range(n))
        def find(a):
            while comp[a] != a:
                a = comp[a]
            return a
        cost = 0
        for i in range(n):
            if wmask >> i & 1:
                cost += wells[i]
        for j in range(m):
            if pmask >> j & 1:
                a, b, c = pipes[j]
                cost += c
                ra, rb = find(a), find(b)
                if ra != rb:
                    comp[ra] = rb
        if best is not None and cost >= best:
            continue
        has = set(find(i) for i in range(n) if wmask >> i & 1)
        if all(find(i) in has for i in range(n)):
            best = cost
