def gen(rng):
    def fmt(n, wells, pipes):
        return '\n'.join([f"{n} {len(pipes)}", ' '.join(map(str, wells))] + [f'{u} {v} {c}' for u, v, c in pipes])
    def rand_pipe(n, cmax):
        u = rng.randrange(n)
        v = rng.randrange(n - 1)
        if v >= u:
            v += 1
        return (u, v, rng.randint(0, cmax))
    tests = [fmt(1, [7], []), fmt(1, [0], []), fmt(3, [1, 1, 1], []), fmt(3, [5, 5, 5], [(0, 1, 1), (1, 2, 1), (0, 2, 1)]),
             fmt(4, [4, 3, 9, 5], [(0, 1, 2), (1, 2, 2), (2, 3, 1)]),
             fmt(2, [10, 10], [(0, 1, 3), (0, 1, 1), (1, 0, 2)]),
             fmt(3, [2, 2, 2], [(0, 1, 5), (1, 2, 5)]),
             fmt(3, [0, 100, 100], [(0, 1, 0), (1, 2, 0)])]
    for n in (2, 3, 4, 5):
        for _ in range(5):
            m = rng.randint(0, 7)
            cmax = rng.choice([3, 9])
            tests.append(fmt(n, [rng.randint(0, cmax + 2) for _ in range(n)], [rand_pipe(n, cmax) for _ in range(m)]))
    def big(n, m, wl, wh, cl, ch, tree=True):
        wells = [rng.randint(wl, wh) for _ in range(n)]
        pipes = []
        if tree:
            perm = list(range(n))
            rng.shuffle(perm)
            for i in range(1, n):
                pipes.append((perm[i], perm[rng.randrange(i)], rng.randint(cl, ch)))
        while len(pipes) < m:
            u = rng.randrange(n)
            v = rng.randrange(n - 1)
            if v >= u:
                v += 1
            pipes.append((u, v, rng.randint(cl, ch)))
        rng.shuffle(pipes)
        return fmt(n, wells, pipes)
    tests.append(big(50000, 100000, 0, 10**5, 0, 10**5))
    tests.append(big(50000, 60000, 10**5 - 10, 10**5, 0, 10))
    tests.append(big(50000, 50000, 0, 20, 10**4, 10**5))
    tests.append(big(50000, 75000, 5 * 10**4, 10**5, 1, 10**5))
    tests.append(big(20000, 100000, 0, 10**5, 0, 10**5, tree=False))
    tests.append(big(3000, 100000, 1000, 10**5, 0, 10**5))
    pipes = [(i, i + 1, 1) for i in range(49999)]
    tests.append(fmt(50000, [10**5 - (i % 7) for i in range(50000)], pipes))
    return tests

